import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        int k = in.nextInt();
        int t = in.nextInt();
        Map<String, Integer> son = new HashMap<>();
        Map<String, Integer> blok = new HashMap<>();
        int m = in.nextInt();
        for (int i = 0; i < m; i++) {
            int vaqt = in.nextInt();
            String hisob = in.next();
            String natija = in.next();
            Integer b = blok.get(hisob);
            if (b != null && vaqt < b + t) {
                System.out.println(vaqt + " " + hisob + " LOCKED");
                continue;
            }
            if (natija.equals("OK")) {
                son.put(hisob, 0);
                System.out.println(vaqt + " " + hisob + " OK");
            } else {
                int x = son.getOrDefault(hisob, 0) + 1;
                son.put(hisob, x);
                if (x >= k) {
                    blok.put(hisob, vaqt);
                    son.put(hisob, 0);
                    System.out.println(vaqt + " " + hisob + " LOCKED");
                } else {
                    System.out.println(vaqt + " " + hisob + " FAIL " + x);
                }
            }
        }
    }
}

